      case "choose_account":
        return (
          <div className="flex flex-col gap-3">
            <p className="text-sm text-gray-700">{t("abha_choose_account")}</p>
            {step.accounts.map((account, i) =>
              accountRow(
                account,
                () => journeyId && selectAccount(journeyId, account),
