import {
  AbdmCareContext,
  AbdmExchange,
  AbdmFacilitySettings,
  AbdmReadiness,
} from "./hip";

export default {
  getFacility: {
    path: "/api/v1/abdm/facility/{facilityId}/",
    method: HttpMethod.GET,
    TRes: Type<AbdmFacilitySettings>(),
