} from "./registry";

const base = "/api/v1/abdm/registry/{facilityId}";

export default {
  get: {
    path: `${base}/`,
    method: HttpMethod.GET,
    TRes: Type<AbdmRegistryOverview>(),
  },
  search: {
    path: `${base}/search/`,
